class Solution:
    def minSwaps(self, data: list[int]) -> int:
        k = sum(data)
        ones = sum(data[:k])
        max_ones = ones
        for i in range(k, len(data)):
            ones += data[i] - data[i - k]
            max_ones = max(max_ones, ones)
        return k - max_ones

