class Solution:
    def maxLevelSum(self, root) -> int:
        queue = deque([root])
        max_sum = float('-inf')
        res = level = 0
        while queue:
            level += 1
            curr_sum = 0
            for _ in range(len(queue)):
                node = queue.popleft()
                curr_sum += node.val
                if node.left: queue.append(node.left)
                if node.right: queue.append(node.right)
            if curr_sum > max_sum:
                max_sum = curr_sum
                res = level
        return res

