                        queue.append((nx, ny))
        return dist

class Solution:
    def lastSubstring(self, s: str) -> str:
        i, j, k = 0, 1, 0
        n = len(s)
        while j + k < n:
            if s[i+k] == s[j+k]:
                k += 1
            elif s[i+k] > s[j+k]:
                j = j + k + 1
                k = 0
            else:
                i = max(i + k + 1, j)
