class Solution:
    def findNumOfValidWords(self, words: list[str], puzzles: list[str]) -> list[int]:
        word_mask_count = Counter()
        for word in words:
            mask = 0
            for c in word:
                mask |= 1 << (ord(c) - ord('a'))
            word_mask_count[mask] += 1
        res = []
        for puzzle in puzzles:
            total = 0
            first = 1 << (ord(puzzle[0]) - ord('a'))
            # Enumerate subsets of puzzle mask that include first letter
            puzzle_mask = 0
            for c in puzzle:
                puzzle_mask |= 1 << (ord(c) - ord('a'))
            sub = puzzle_mask
            while sub:
                if sub & first:
                    total += word_mask_count[sub]
                sub = (sub - 1) & puzzle_mask
            res.append(total)
        return res

