class Solution:
    def kConcatenationMaxSum(self, arr: list[int], k: int) -> int:
        MOD = 10**9 + 7
        def kadane(a):
            max_sum = cur = 0
            for x in a:
                cur = max(0, cur + x)
                max_sum = max(max_sum, cur)
            return max_sum
        single = kadane(arr)
        if k == 1:
            return single % MOD
        double = kadane(arr + arr)
        total = sum(arr)
        if total > 0:
            return (double + (k - 2) * total) % MOD
        return double % MOD

class Solution:
    def criticalConnections(self, n: int, connections: list[list[int]]) -> list[list[int]]:
        graph = [[] for _ in range(n)]
        for u, v in connections:
            graph[u].append(v)
            graph[v].append(u)
        disc = [-1] * n
        low = [0] * n
        res = []
        self.timer = 0
        def dfs(u, parent):
            disc[u] = low[u] = self.timer
            self.timer += 1
            for v in graph[u]:
                if v == parent:
                    continue
                if disc[v] == -1:
                    dfs(v, u)
                    low[u] = min(low[u], low[v])
                    if low[v] > disc[u]:
                        res.append([u, v])
                else:
                    low[u] = min(low[u], disc[v])
        dfs(0, -1)
        return res

