class FizzBuzz:
    def __init__(self, n: int):
        self.n = n
        self.current = 1
        self.lock = threading.Lock()
        self.cond = threading.Condition(self.lock)

    def _run(self, check_fn, output_fn):
        while True:
            with self.cond:
                while self.current <= self.n and not check_fn(self.current):
                    self.cond.wait()
                if self.current > self.n:
                    return
                output_fn(self.current)
                self.current += 1
                self.cond.notify_all()

    def fizz(self, printFizz):
        self._run(lambda x: x%3==0 and x%5!=0, lambda x: printFizz())

    def buzz(self, printBuzz):
        self._run(lambda x: x%5==0 and x%3!=0, lambda x: printBuzz())

    def fizzbuzz(self, printFizzBuzz):
        self._run(lambda x: x%15==0, lambda x: printFizzBuzz())

    def number(self, printNumber):
        self._run(lambda x: x%3!=0 and x%5!=0, lambda x: printNumber(x))

